// Brand marks for the channels and systems EASM connects to: WhatsApp, Messenger, Instagram, Moodle,
// Koha, PeopleSoft, SAP, the website platforms, ad networks, CRMs and payment schemes. They show which
// service a conversation, sign-in or integration belongs to; they are never used as general UI icons.
//
// Artwork comes from each brand's own published mark: single-colour glyphs from Simple Icons
// (simple-icons 16.33.0, CC0 data), the Koha pictogram from the Koha source, and faithful redraws of the
// four-colour Google G, the Gmail M, the Microsoft squares, the Oracle ring, the LinkedIn bug, the
// Salesforce cloud, the Mastercard circles, the 1LINK oval and the Easypaisa e (the last two from the logos on their own
// sites). JazzCash's symbol is the vector on its own site. A brand that publishes no mark for reuse (Blackboard, D2L,
// Ellucian, Workday) gets a monogram set in Inter Bold, which names it without imitating its logo. Each
// entry records its source. The marks remain trademarks of their owners: show them unaltered (no
// recolouring beyond the appearances below, no stretching) and only to refer to the service itself.
import { forwardRef, type CSSProperties, type HTMLAttributes } from 'react';

/** channel: where a conversation happens. campus: LMS, student records, library. workplace: sign-in,
 * meetings, forms. business: ERP, CRM, HR, automation. content: websites and file stores. marketing: ad
 * networks, analytics and email marketing. payments: card schemes and gateways. */
export type BrandIconCategory = 'channel' | 'campus' | 'workplace' | 'business' | 'content' | 'marketing' | 'payments';
export interface BrandIconDefinition {
  title: string;
  category: BrandIconCategory;
  /** The brand's primary colour. */
  color: string;
  /** A darker shade of the brand colour for the glyph on a tinted tile, where the brand colour is too light to read. */
  ink?: string;
  /** Background of the solid tile when it is not the plain brand colour (Instagram's gradient). */
  solid?: string;
  /** Keeps its own colours in every appearance except mono (Google, Gmail, Microsoft, Mastercard, 1LINK, JazzCash, Easypaisa). */
  multicolor?: boolean;
  /** Letters, not the brand's logo: the brand publishes no mark for reuse. */
  monogram?: boolean;
  viewBox: string;
  /** backdrop: a fill behind the mark (1LINK's orange oval), drawn only where the mark keeps its own colours. */
  paths: readonly { d: string; fill?: string; rule?: 'evenodd'; backdrop?: boolean }[];
  source: string;
  note: string;
}

